INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22501, 'តាមនិយមន័យ ប៉ារ៉ាបូលគឺជាសំណុំចំណុច \(M\) ក្នុងប្លង់ដែលមានចម្ងាយពីកំណុំ \(F\) ស្មើនឹងអ្វី?', NULL, '["ចម្ងាយពី \\(M\\) ទៅបន្ទាត់ប្រាប់ទិស \\(\\Delta\\)", "ពាក់កណ្ដាលចម្ងាយពី \\(M\\) ទៅបន្ទាត់ប្រាប់ទិស \\(\\Delta\\)", "ពីរដងចម្ងាយពី \\(M\\) ទៅកំពូល", "ថេរ \\(2a\\) ពីកំពូល"]', 0, NULL, 1, 'mcq', 'តាមនិយមន័យ ប៉ារ៉ាបូលគឺជាសំណុំចំណុច \(M\) ដែល \(MF = d(M, \Delta)\) ។', 'និយមន័យប៉ារ៉ាបូល', 'easy', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22502, 'រកកូអរដោនេកំណុំ \(F\) នៃប៉ារ៉ាបូល \(x^2 = 8y\) ។', NULL, '["\\(F(0, 4)\\)", "\\(F(0, -2)\\)", "\\(F(2, 0)\\)", "\\(F(0, 2)\\)"]', 3, NULL, 1, 'mcq', 'សមីការមានរាង \(x^2 = 4py\) ដែល \(4p = 8 \Rightarrow p = 2\) ដូច្នេះ \(F(0, 2)\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូលនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22503, 'រកកូអរដោនេកំពូល \(I(h, k)\) នៃប៉ារ៉ាបូល \((y - 3)^2 = 8(x + 2)\) ។', NULL, '["\\(I(2, -3)\\)", "\\(I(-2, 3)\\)", "\\(I(3, -2)\\)", "\\(I(-3, 2)\\)"]', 1, NULL, 1, 'mcq', 'ប្រៀបធៀបនឹង \((y - k)^2 = 4p(x - h)\) បាន \(h = -2\) និង \(k = 3\) ដូច្នេះ \(I(-2, 3)\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'easy', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22504, 'រកសមីការបន្ទាត់ប្រាប់ទិស \(\Delta\) នៃប៉ារ៉ាបូល \(y^2 = -12x\) ។', NULL, '["\\(x = 3\\)", "\\(y = -3\\)", "\\(y = 3\\)", "\\(x = -3\\)"]', 0, NULL, 1, 'mcq', 'សមីការមានរាង \(y^2 = 4px\) ដែល \(4p = -12 \Rightarrow p = -3\) ដូច្នេះបន្ទាត់ប្រាប់ទិសគឺ \(x = -p = 3\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូលនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22505, 'រកសមីការអ័ក្សឆ្លុះនៃប៉ារ៉ាបូល \((x - 5)^2 = -12(y + 1)\) ។', NULL, '["\\(y = 1\\)", "\\(x = 5\\)", "\\(x = -5\\)", "\\(y = -1\\)"]', 1, NULL, 1, 'mcq', 'ប៉ារ៉ាបូលមានអ័ក្សឆ្លុះឈរកាត់តាមកំពូល \(I(5, -1)\) ដូច្នេះអ័ក្សឆ្លុះគឺ \(x = 5\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'easy', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22506, 'តើប៉ារ៉ាបូល \(x^2 = -16y\) បើកទៅទិសណា?', NULL, '["ទៅឆ្វេង", "ទៅស្ដាំ", "ឡើងលើ", "ចុះក្រោម"]', 3, NULL, 1, 'mcq', 'សមីការ \(x^2 = 4py\) មាន \(4p = -16 \Rightarrow p = -4 < 0\) ដូច្នេះប៉ារ៉ាបូលបើកចុះក្រោម ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូលនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22507, 'ចំពោះប៉ារ៉ាបូល \((x + 1)^2 = 20(y - 4)\) តើតម្លៃប៉ារ៉ាម៉ែត្រ \(p\) ស្មើប៉ុន្មាន?', NULL, '["\\(10\\)", "\\(5\\)", "\\(4\\)", "\\(20\\)"]', 1, NULL, 1, 'mcq', 'សមីការមានរាង \((x - h)^2 = 4p(y - k)\) ដូច្នេះ \(4p = 20 \Rightarrow p = 5\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'easy', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22508, 'រកសមីការស្ដង់ដារនៃប៉ារ៉ាបូលដែលមានកំពូល \(O(0, 0)\) និងកំណុំ \(F(3, 0)\) ។', NULL, '["\\(y^2 = 6x\\)", "\\(x^2 = 12y\\)", "\\(y^2 = 12x\\)", "\\(y^2 = -12x\\)"]', 2, NULL, 1, 'mcq', 'កំណុំ \(F(3, 0)\) ស្ថិតលើអ័ក្ស \(Ox\) ដោយ \(p = 3\) នាំឱ្យ \(y^2 = 4(3)x = 12x\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូលនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22509, 'រកសមីការស្ដង់ដារនៃប៉ារ៉ាបូលដែលមានកំពូល \(O(0, 0)\) និងបន្ទាត់ប្រាប់ទិស \(y = -5\) ។', NULL, '["\\(x^2 = -20y\\)", "\\(x^2 = 10y\\)", "\\(x^2 = 20y\\)", "\\(y^2 = 20x\\)"]', 2, NULL, 1, 'mcq', 'បន្ទាត់ប្រាប់ទិស \(y = -p = -5 \Rightarrow p = 5\) ដូច្នេះ \(x^2 = 4(5)y = 20y\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូលនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22510, 'រកប្រវែងអង្កត់ធ្នូកាត់កំណុំកែងអ័ក្សឆ្លុះ (latus rectum) នៃប៉ារ៉ាបូល \(y^2 = -24x\) ។', NULL, '["\\(24\\)", "\\(12\\)", "\\(6\\)", "\\(48\\)"]', 0, NULL, 1, 'mcq', 'ប្រវែងអង្កត់ធ្នូកាត់កំណុំកែងអ័ក្សឆ្លុះស្មើ \(|4p| = |-24| = 24\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូលនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22511, 'រកកូអរដោនេកំណុំ \(F\) នៃប៉ារ៉ាបូល \((x - 2)^2 = 12(y + 1)\) ។', NULL, '["\\(F(2, 2)\\)", "\\(F(2, -4)\\)", "\\(F(5, -1)\\)", "\\(F(2, 3)\\)"]', 0, NULL, 2, 'mcq', 'កំពូល \(I(2, -1)\) និង \(4p = 12 \Rightarrow p = 3\) ។ កំណុំគឺ \(F(h, k + p) = F(2, -1 + 3) = F(2, 2)\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22512, 'រកសមីការប៉ារ៉ាបូលដែលមានកំពូល \(O(0, 0)\) អ័ក្សឆ្លុះជាអ័ក្សអរដោនេ និងកាត់តាមចំណុច \(A(6, 9)\) ។', NULL, '["\\(x^2 = 9y\\)", "\\(y^2 = 4x\\)", "\\(x^2 = 6y\\)", "\\(x^2 = 4y\\)"]', 3, NULL, 2, 'mcq', 'សមីការមានរាង \(x^2 = 4py\) ។ ជំនួស \(A(6, 9)\) បាន \(36 = 36p \Rightarrow p = 1\) ដូច្នេះ \(x^2 = 4y\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូលនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22513, 'ចំណុច \(M(6, 3)\) ស្ថិតនៅលើប៉ារ៉ាបូល \(x^2 = 12y\) ។ រកចម្ងាយពី \(M\) ទៅកំណុំ \(F\) ។', NULL, '["\\(6\\)", "\\(3\\)", "\\(12\\)", "\\(9\\)"]', 0, NULL, 2, 'mcq', 'គេមាន \(4p = 12 \Rightarrow p = 3\) បន្ទាត់ប្រាប់ទិស \(y = -3\) ។ ដូច្នេះ \(MF = y_M + p = 3 + 3 = 6\) ។', 'និយមន័យប៉ារ៉ាបូល', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22514, 'រកសមីការបន្ទាត់ប៉ះប៉ារ៉ាបូល \(x^2 = 8y\) ត្រង់ចំណុច \(M(4, 2)\) ។', NULL, '["\\(y = x + 2\\)", "\\(y = -x + 6\\)", "\\(y = x - 2\\)", "\\(y = 2x - 6\\)"]', 2, NULL, 2, 'mcq', 'រូបមន្តបន្ទាត់ប៉ះត្រង់ \((x_0, y_0)\) គឺ \(x_0 x = 4(y + y_0)\) ។ ជំនួស \((4, 2)\) បាន \(4x = 4(y + 2) \Rightarrow y = x - 2\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22515, 'រកសមីការបន្ទាត់ប្រាប់ទិសនៃប៉ារ៉ាបូល \((y + 4)^2 = -8(x - 3)\) ។', NULL, '["\\(x = 1\\)", "\\(x = 5\\)", "\\(y = -6\\)", "\\(y = -2\\)"]', 1, NULL, 2, 'mcq', 'កំពូល \(I(3, -4)\) និង \(4p = -8 \Rightarrow p = -2\) ។ បន្ទាត់ប្រាប់ទិសគឺ \(x = h - p = 3 - (-2) = 5\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22516, 'រកសមីការបន្ទាត់ប៉ះប៉ារ៉ាបូល \(y^2 = 12x\) ត្រង់ចំណុច \(M(3, -6)\) ។', NULL, '["\\(x + y - 3 = 0\\)", "\\(x - y - 9 = 0\\)", "\\(x + y + 3 = 0\\)", "\\(2x + y = 0\\)"]', 2, NULL, 2, 'mcq', 'ប្រើរូបមន្ត \(y_0 y = 6(x + x_0)\) បាន \(-6y = 6(x + 3) \Rightarrow x + y + 3 = 0\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22517, 'រកកូអរដោនេកំពូលនៃប៉ារ៉ាបូល \(x^2 - 6x - 8y + 17 = 0\) ។', NULL, '["\\(I(3, 2)\\)", "\\(I(3, 1)\\)", "\\(I(3, -1)\\)", "\\(I(-3, 1)\\)"]', 1, NULL, 2, 'mcq', 'បំប្លែងជាការេពេញ \((x - 3)^2 = 8y - 17 + 9 = 8(y - 1)\) ដូច្នេះកំពូលគឺ \(I(3, 1)\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22518, 'រកតម្លៃវិជ្ជមាន \(m > 0\) ដើម្បីឱ្យបន្ទាត់ \(y = mx - 4\) ប៉ះប៉ារ៉ាបូល \(x^2 = 4y\) ។', NULL, '["\\(m = 4\\)", "\\(m = 8\\)", "\\(m = 2\\)", "\\(m = 1\\)"]', 2, NULL, 2, 'mcq', 'ជំនួស \(y\) បាន \(x^2 - 4mx + 16 = 0\) ។ លក្ខខណ្ឌប៉ះ \(\Delta'' = 4m^2 - 16 = 0 \Rightarrow m = 2\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22519, 'រកកូអរដោនេកំណុំនៃប៉ារ៉ាបូល \(y^2 + 4y + 12x - 20 = 0\) ។', NULL, '["\\(F(-1, 2)\\)", "\\(F(2, -2)\\)", "\\(F(5, -2)\\)", "\\(F(-1, -2)\\)"]', 3, NULL, 2, 'mcq', 'សរសេរជា \((y + 2)^2 = -12(x - 2)\) បានកំពូល \(I(2, -2)\) និង \(p = -3\) ដូច្នេះ \(F(2 - 3, -2) = F(-1, -2)\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22520, 'រកតម្លៃ \(k\) ដើម្បីឱ្យបន្ទាត់ \(y = x + k\) ប៉ះប៉ារ៉ាបូល \(x^2 = 16y\) ។', NULL, '["\\(k = -8\\)", "\\(k = -4\\)", "\\(k = 4\\)", "\\(k = -2\\)"]', 1, NULL, 2, 'mcq', 'សមីការអាប់ស៊ីសចំណុចប្រសព្វគឺ \(x^2 - 16x - 16k = 0\) ។ ដោយ \(\Delta'' = 64 + 16k = 0\) បាន \(k = -4\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22521, 'រកសមីការស្ដង់ដារនៃប៉ារ៉ាបូលដែលមានកំពូល \(I(2, -3)\) និងកំណុំ \(F(2, 1)\) ។', NULL, '["\\((x - 2)^2 = 16(y + 3)\\)", "\\((y + 3)^2 = 16(x - 2)\\)", "\\((x - 2)^2 = 4(y + 3)\\)", "\\((x - 2)^2 = -16(y + 3)\\)"]', 0, NULL, 2, 'mcq', 'កំពូល និងកំណុំមានអាប់ស៊ីស \(x = 2\) ដូចគ្នា ដោយ \(p = 1 - (-3) = 4\) នាំឱ្យ \((x - 2)^2 = 16(y + 3)\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22522, 'រកសមីការស្ដង់ដារនៃប៉ារ៉ាបូលដែលមានកំពូល \(I(-1, 4)\) និងបន្ទាត់ប្រាប់ទិស \(x = 2\) ។', NULL, '["\\((x + 1)^2 = -12(y - 4)\\)", "\\((y - 4)^2 = -6(x + 1)\\)", "\\((y - 4)^2 = -12(x + 1)\\)", "\\((y - 4)^2 = 12(x + 1)\\)"]', 2, NULL, 2, 'mcq', 'បន្ទាត់ប្រាប់ទិស \(x = 2\) នៅខាងស្ដាំកំពូល \(x = -1\) ដូច្នេះ \(p = -1 - 2 = -3\) នាំឱ្យ \((y - 4)^2 = -12(x + 1)\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22523, 'រកសមីការស្ដង់ដារនៃប៉ារ៉ាបូលដែលមានកំណុំ \(F(5, 2)\) និងបន្ទាត់ប្រាប់ទិស \(x = -1\) ។', NULL, '["\\((y - 2)^2 = -12(x - 2)\\)", "\\((y - 2)^2 = 6(x - 2)\\)", "\\((x - 2)^2 = 12(y - 2)\\)", "\\((y - 2)^2 = 12(x - 2)\\)"]', 3, NULL, 2, 'mcq', 'កំពូលនៅចំណុចកណ្ដាល \(h = \frac{5 + (-1)}{2} = 2, k = 2\) និង \(p = 5 - 2 = 3\) ដូច្នេះ \((y - 2)^2 = 12(x - 2)\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22524, 'រកសមីការបន្ទាត់ប្រាប់ទិសនៃប៉ារ៉ាបូល \(y^2 - 8y - 4x + 12 = 0\) ។', NULL, '["\\(y = 4\\)", "\\(x = -1\\)", "\\(x = 0\\)", "\\(x = -2\\)"]', 3, NULL, 2, 'mcq', 'សរសេរជា \((y - 4)^2 = 4(x + 1)\) បាន \(h = -1, p = 1\) ដូច្នេះបន្ទាត់ប្រាប់ទិសគឺ \(x = -1 - 1 = -2\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'medium', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22525, 'រកសមីការសំណុំចំណុច \(M(x, y)\) ដែលមានចម្ងាយពីចំណុច \(F(1, 2)\) ស្មើនឹងចម្ងាយពីបន្ទាត់ \(y = -4\) ។', NULL, '["\\((x - 1)^2 = 12(y - 1)\\)", "\\((x - 1)^2 = 12(y + 1)\\)", "\\((y + 1)^2 = 12(x - 1)\\)", "\\((x - 1)^2 = 6(y + 1)\\)"]', 1, NULL, 3, 'mcq', 'តាមលក្ខខណ្ឌ \((x - 1)^2 + (y - 2)^2 = (y + 4)^2\) ពន្លាតនិងសម្រួលបាន \((x - 1)^2 = 12(y + 1)\) ។', 'និយមន័យប៉ារ៉ាបូល', 'hard', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22526, 'រកសមីការប៉ារ៉ាបូលមានអ័ក្សឆ្លុះឈរ និងកាត់តាមចំណុច \((0, 0), (2, 0), (3, 3)\) ។', NULL, '["\\((x + 1)^2 = y + 1\\)", "\\((x - 1)^2 = 2(y + 1)\\)", "\\((x - 1)^2 = y + 1\\)", "\\((x - 1)^2 = 4(y + 1)\\)"]', 2, NULL, 3, 'mcq', 'យក \(y = ax^2 + bx + c\) ជំនួសចំណុចទាំងបីបាន \(c = 0, b = -2, a = 1\) ឬ \(y = x^2 - 2x \Leftrightarrow (x - 1)^2 = y + 1\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'hard', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22527, 'រកសមីការបន្ទាត់ប៉ះប៉ារ៉ាបូល \(y^2 = 8x\) ដែលស្របនឹងបន្ទាត់ \(2x - y + 5 = 0\) ។', NULL, '["\\(2x - y - 1 = 0\\)", "\\(2x - y - 4 = 0\\)", "\\(2x - y + 2 = 0\\)", "\\(2x - y + 1 = 0\\)"]', 3, NULL, 3, 'mcq', 'បន្ទាត់ស្របមានរាង \(y = 2x + c\) ។ ជំនួសចូលប៉ារ៉ាបូលបាន \(4x^2 + (4c - 8)x + c^2 = 0\) ។ \(\Delta'' = 16 - 16c = 0 \Rightarrow c = 1\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'hard', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22528, 'បន្ទាត់មួយកាត់តាមកំណុំនៃប៉ារ៉ាបូល \(x^2 = 8y\) ដោយមានមេគុណប្រាប់ទិស \(\frac{3}{4}\) កាត់ប៉ារ៉ាបូលត្រង់ \(A\) និង \(B\) ។ រកប្រវែងអង្កត់ធ្នូ \(AB\) ។', NULL, '["\\(\\frac{25}{2}\\)", "\\(16\\)", "\\(12\\)", "\\(\\frac{21}{2}\\)"]', 0, NULL, 3, 'mcq', 'កំណុំ \(F(0, 2)\) បន្ទាត់ \(y = \frac{3}{4}x + 2\) ប្រសព្វត្រង់ \(x_1 = -2, x_2 = 8\) ។ ដោយ \(y_1 = \frac{1}{2}, y_2 = 8\) បាន \(AB = y_1 + y_2 + 2p = \frac{25}{2}\) ។', 'សមីការប៉ារ៉ាបូលដែលមានកំពូលនៅគល់ O(0, 0)', 'hard', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22529, 'ចំណុច \(M(x_0, y_0)\) ស្ថិតនៅលើប៉ារ៉ាបូល \(y^2 = 16x\) និងមានចម្ងាយពីកំណុំស្មើ \(10\) ។ រកអាប់ស៊ីស \(x_0\) ។', NULL, '["\\(8\\)", "\\(6\\)", "\\(4\\)", "\\(14\\)"]', 1, NULL, 3, 'mcq', 'គេមាន \(4p = 16 \Rightarrow p = 4\) ។ តាមនិយមន័យ \(MF = x_0 + p = 10 \Rightarrow x_0 = 6\) ។', 'និយមន័យប៉ារ៉ាបូល', 'hard', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22530, 'រកសមីការបន្ទាត់ប៉ះប៉ារ៉ាបូល \(x^2 - 4x - 8y + 20 = 0\) ដែលកែងនឹងបន្ទាត់ \(x + y - 3 = 0\) ។', NULL, '["\\(x - y + 2 = 0\\)", "\\(x - y - 4 = 0\\)", "\\(x - y - 2 = 0\\)", "\\(x + y - 2 = 0\\)"]', 2, NULL, 3, 'mcq', 'បន្ទាត់កែងមានមេគុណប្រាប់ទិស \(m = 1\) ដូច្នេះ \(y = x + c\) ។ ជំនួសបាន \(x^2 - 12x + 20 - 8c = 0\) ។ \(\Delta'' = 16 + 8c = 0 \Rightarrow c = -2\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'hard', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22531, 'រកតម្លៃ \(k\) ដើម្បីឱ្យបន្ទាត់ \(2x - y + k = 0\) ប៉ះប៉ារ៉ាបូល \(x^2 = 12y\) ។', NULL, '["\\(k = -12\\)", "\\(k = -6\\)", "\\(k = -24\\)", "\\(k = 12\\)"]', 0, NULL, 3, 'mcq', 'ជំនួស \(y = 2x + k\) បាន \(x^2 - 24x - 12k = 0\) ។ លក្ខខណ្ឌ \(\Delta'' = 144 + 12k = 0 \Rightarrow k = -12\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'hard', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-6a00687f3d.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22532, 'ត្រែទទួលរលកផ្កាយរណបរាងប៉ារ៉ាបូលមួយមានមាត់ទទឹង \(6\text{ m}\) និងជម្រៅ \(0.75\text{ m}\) ដូចរូប ។ តើឧបករណ៍ទទួលរលក (នៅកំណុំ) ស្ថិតនៅចម្ងាយប៉ុន្មានពីកំពូល \(O\) ?', 'g12sc-6a00687f3d.svg', '["\\(1.5\\text{ m}\\)", "\\(2.25\\text{ m}\\)", "\\(6\\text{ m}\\)", "\\(3\\text{ m}\\)"]', 3, NULL, 3, 'mcq', 'គែមត្រែមានកូអរដោនេ \((3, 0.75)\) ។ ជំនួសក្នុង \(x^2 = 4py\) បាន \(9 = 3p \Rightarrow p = 3\text{ m}\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'pisa', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-16244004e1.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22533, 'កញ្ចក់ចាំងពន្លឺចង្កៀងរថយន្តរាងប៉ារ៉ាបូលមានអំពូលស្ថិតនៅកំណុំ \(F(0, 2)\) (ចម្ងាយ \(2\text{ cm}\) ពីកំពូល) និងមាត់មានអង្កត់ផ្ចិត \(16\text{ cm}\) ។ រកជម្រៅនៃកញ្ចក់ចាំងពន្លឺ ។', 'g12sc-16244004e1.svg', '["\\(8\\text{ cm}\\)", "\\(4\\text{ cm}\\)", "\\(10\\text{ cm}\\)", "\\(16\\text{ cm}\\)"]', 0, NULL, 3, 'mcq', 'ដោយ \(p = 2\) សមីការគឺ \(x^2 = 8y\) ។ នៅគែមមាត់ \(x = 8\) បាន \(64 = 8y \Rightarrow y = 8\text{ cm}\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'pisa', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-21b20ce34c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22534, 'ស្ពានកោងរាងប៉ារ៉ាបូលមួយមានប្រវែងកំណោង \(40\text{ m}\) និងកម្ពស់អតិបរមានៅចំណុចកណ្ដាល \(10\text{ m}\) ពីផ្ទៃទឹក ។ រកកម្ពស់កំណោងស្ពានត្រង់ចម្ងាយ \(10\text{ m}\) ពីចំណុចកណ្ដាល ។', 'g12sc-21b20ce34c.svg', '["\\(8.5\\text{ m}\\)", "\\(6.5\\text{ m}\\)", "\\(5\\text{ m}\\)", "\\(7.5\\text{ m}\\)"]', 3, NULL, 3, 'mcq', 'សមីការប៉ារ៉ាបូលគឺ \(x^2 = -40(y - 10)\) ។ ជំនួស \(x = 10\) បាន \(100 = -40(y - 10) \Rightarrow y = 7.5\text{ m}\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'pisa', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-ba08f354ea.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22535, 'ខ្សែកាបរាងប៉ារ៉ាបូលនៃស្ពានយោលមួយភ្ជាប់រវាងប៉មពីរមានចម្ងាយ \(120\text{ m}\) ពីគ្នា ។ ចំណុចទាបបំផុតនៃខ្សែកាបនៅខ្ពស់ \(5\text{ m}\) ពីផ្ទៃស្ពាន ហើយចុងខ្សែនៅលើប៉មខ្ពស់ \(20\text{ m}\) ។ រកកម្ពស់ខ្សែកាបត្រង់ចម្ងាយ \(30\text{ m}\) ពីចំណុចកណ្ដាល ។', 'g12sc-ba08f354ea.svg', '["\\(12.5\\text{ m}\\)", "\\(8.75\\text{ m}\\)", "\\(7.5\\text{ m}\\)", "\\(10\\text{ m}\\)"]', 1, NULL, 3, 'mcq', 'យក \(x^2 = 4p(y - 5)\) កាត់តាម \((60, 20)\) បាន \(4p = 240\) ។ ត្រង់ \(x = 30\) បាន \(900 = 240(y - 5) \Rightarrow y = 8.75\text{ m}\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'pisa', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-a4e2640b4e.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22536, 'ក្បាលបាញ់ទឹកនៅគល់ \(O(0, 0)\) បាញ់ទឹកឡើងជាខ្សែកោងប៉ារ៉ាបូលដោយឈានដល់កម្ពស់អតិបរមា \(4.5\text{ m}\) ត្រង់ចម្ងាយដេក \(3\text{ m}\) ។ តើទឹកធ្លាក់ដល់ដីនៅចម្ងាយដេកប៉ុន្មានម៉ែត្រពីក្បាលបាញ់?', 'g12sc-a4e2640b4e.svg', '["\\(7.5\\text{ m}\\)", "\\(9\\text{ m}\\)", "\\(6\\text{ m}\\)", "\\(4.5\\text{ m}\\)"]', 2, NULL, 3, 'mcq', 'ដោយអ័ក្សឆ្លុះគឺ \(x = 3\) ហើយទឹកចេញពី \(x = 0\) ដូច្នេះទឹកធ្លាក់ដល់ដីវិញត្រង់ \(x = 2 \times 3 = 6\text{ m}\) ។', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'pisa', 1, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22537, 'គេមានប៉ារ៉ាបូលដែលមានសមីការ \(x^2 = -20y\) ។ រកកំពូល កំណុំ បន្ទាត់ប្រាប់ទិស និងអ័ក្សឆ្លុះនៃប៉ារ៉ាបូលនេះ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្រៀបធៀបសមីការនឹងរាងស្ដង់ដារ \(x^2 = 4py\) គេបានកំពូល \(O(0, 0)\) (1 ពិន្ទុ)
រកប៉ារ៉ាម៉ែត្រ \(4p = -20 \Rightarrow p = -5 < 0\) (បើកចុះក្រោម) (1 ពិន្ទុ)
កូអរដោនេកំណុំគឺ \(F(0, p) = F(0, -5)\) (1 ពិន្ទុ)
សមីការបន្ទាត់ប្រាប់ទិសគឺ \(y = -p = 5\) (1 ពិន្ទុ)
សមីការអ័ក្សឆ្លុះគឺអ័ក្សអរដោនេ \(x = 0\) ។ (1 ពិន្ទុ)', 'សមីការប៉ារ៉ាបូលដែលមានកំពូលនៅគល់ O(0, 0)', 'easy', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22538, 'ចូរសរសេរសមីការប៉ារ៉ាបូល \(x^2 - 6x - 12y - 15 = 0\) ជាទម្រង់ស្ដង់ដារ រួចរកកំពូល កំណុំ និងបន្ទាត់ប្រាប់ទិស ។', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្ដុំតួជាប់ \(x\) ជាការេពេញ៖ \(x^2 - 6x + 9 = 12y + 15 + 9\) (1 ពិន្ទុ)
សរសេរជាទម្រង់ស្ដង់ដារ \((x - 3)^2 = 12(y + 2)\) (1 ពិន្ទុ)
កំណត់កំពូល \(I(3, -2)\) និងប៉ារ៉ាម៉ែត្រ \(4p = 12 \Rightarrow p = 3\) (1 ពិន្ទុ)
រកកំណុំ \(F(h, k + p) = F(3, -2 + 3) = F(3, 1)\) (1 ពិន្ទុ)
រកសមីការបន្ទាត់ប្រាប់ទិស \(y = k - p = -2 - 3 = -5\) ។ (1 ពិន្ទុ)', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'medium', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22539, 'រកសមីការប៉ារ៉ាបូលដែលមានកំពូល \(O(0, 0)\) អ័ក្សឆ្លុះជាអ័ក្សអាប់ស៊ីស និងកាត់តាមចំណុច \(A(-3, 6)\) រួចរកកំណុំ និងបន្ទាត់ប្រាប់ទិស ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដោយអ័ក្សឆ្លុះជាអ័ក្ស \(Ox\) សមីការមានរាង \(y^2 = 4px\) (1 ពិន្ទុ)
ជំនួសកូអរដោនេ \(A(-3, 6)\) បាន \(6^2 = 4p(-3) \Rightarrow 36 = -12p\) (1 ពិន្ទុ)
ដោះស្រាយរក \(p = -3\) ដូច្នេះសមីការគឺ \(y^2 = -12x\) (1 ពិន្ទុ)
កូអរដោនេកំណុំគឺ \(F(p, 0) = F(-3, 0)\) (1 ពិន្ទុ)
សមីការបន្ទាត់ប្រាប់ទិសគឺ \(x = -p = 3\) ។ (1 ពិន្ទុ)', 'សមីការប៉ារ៉ាបូលដែលមានកំពូលនៅគល់ O(0, 0)', 'medium', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22540, 'ផ្ទៀងផ្ទាត់ថាចំណុច \(M(8, 4)\) ស្ថិតនៅលើប៉ារ៉ាបូល \(x^2 = 16y\) រួចរកសមីការបន្ទាត់ប៉ះប៉ារ៉ាបូលត្រង់ចំណុច \(M\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស \((8, 4)\) ចូលសមីការប៉ារ៉ាបូល៖ \(8^2 = 64 = 16(4)\) ពិត (1 ពិន្ទុ)
សរសេររូបមន្តបន្ទាត់ប៉ះត្រង់ \((x_0, y_0)\) ៖ \(x_0 x = 2p(y + y_0)\) (1 ពិន្ទុ)
ដោយ \(4p = 16 \Rightarrow 2p = 8\) និង \((x_0, y_0) = (8, 4)\) (1 ពិន្ទុ)
ជំនួសតម្លៃបាន \(8x = 8(y + 4)\) (1 ពិន្ទុ)
សម្រួលបានសមីការបន្ទាត់ប៉ះគឺ \(x - y - 4 = 0\) ឬ \(y = x - 4\) ។ (1 ពិន្ទុ)', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'medium', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22541, 'រកសមីការស្ដង់ដារនៃប៉ារ៉ាបូលដែលមានកំណុំ \(F(4, -1)\) និងបន្ទាត់ប្រាប់ទិស \(x = -2\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដោយបន្ទាត់ប្រាប់ទិសឈរ \(x = -2\) ប៉ារ៉ាបូលមានអ័ក្សឆ្លុះដេក \(y = -1\) (1 ពិន្ទុ)
កំពូល \(I(h, k)\) ជាចំណុចកណ្ដាលរវាងកំណុំនិងបន្ទាត់ប្រាប់ទិស៖ \(h = \frac{4 + (-2)}{2} = 1, k = -1\) (1 ពិន្ទុ)
រកប៉ារ៉ាម៉ែត្រ \(p = 4 - 1 = 3 > 0\) (1 ពិន្ទុ)
ជំនួសក្នុងទម្រង់ស្ដង់ដារ \((y - k)^2 = 4p(x - h)\) (1 ពិន្ទុ)
គេបានសមីការស្ដង់ដារគឺ \((y + 1)^2 = 12(x - 1)\) ។ (1 ពិន្ទុ)', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'medium', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22542, 'រកសមីការប៉ារ៉ាបូលដែលមានអ័ក្សឆ្លុះឈរ និងកាត់តាមចំណុច \(A(1, 4), B(2, 1), C(4, 7)\) រួចរកកំពូល និងកំណុំរបស់វា ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាងសមីការប៉ារ៉ាបូលរាង \(y = ax^2 + bx + c\) រួចជំនួសចំណុចទាំងបី៖ \(a+b+c=4, \; 4a+2b+c=1, \; 16a+4b+c=7\) (1 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធសមីការបាន \(a = 2, \; b = -9, \; c = 11\) ដូច្នេះ \(y = 2x^2 - 9x + 11\) (1 ពិន្ទុ)
បំប្លែងជាទម្រង់ស្ដង់ដារ \(\left(x - \frac{9}{4}\right)^2 = \frac{1}{2}\left(y - \frac{7}{8}\right)\) (1 ពិន្ទុ)
កំពូលគឺ \(I\left(\frac{9}{4}, \frac{7}{8}\right)\) និង \(4p = \frac{1}{2} \Rightarrow p = \frac{1}{8}\) (1 ពិន្ទុ)
កំណុំគឺ \(F\left(\frac{9}{4}, \frac{7}{8} + \frac{1}{8}\right) = F\left(\frac{9}{4}, 1\right)\) ។ (1 ពិន្ទុ)', 'សមីការប៉ារ៉ាបូលដែលមានកំពូល I(h, k)', 'hard', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22543, 'រកសមីការបន្ទាត់ប៉ះប៉ារ៉ាបូល \(y^2 = 12x\) ដែលគូសចេញពីចំណុច \(A(-3, 0)\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'បន្ទាត់មិនឈរកាត់តាម \(A(-3, 0)\) មានសមីការ \(y = m(x + 3)\) (បន្ទាត់ \(x = -3\) មិនប៉ះប៉ារ៉ាបូលទេ) (1 ពិន្ទុ)
ជំនួស \(y\) ចូល \(y^2 = 12x\) បាន \(m^2 x^2 + (6m^2 - 12)x + 9m^2 = 0\) (1 ពិន្ទុ)
លក្ខខណ្ឌប៉ះ \(\Delta'' = (3m^2 - 6)^2 - 9m^4 = -36m^2 + 36 = 0\) (1 ពិន្ទុ)
ដោះស្រាយបាន \(m^2 = 1 \Rightarrow m = 1\) ឬ \(m = -1\) (1 ពិន្ទុ)
ដូច្នេះបន្ទាត់ប៉ះទាំងពីរគឺ \(y = x + 3\) និង \(y = -x - 3\) ។ (1 ពិន្ទុ)', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'hard', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22544, 'ដោយប្រើនិយមន័យប៉ារ៉ាបូល ចូររកសមីការសំណុំចំណុច \(M(x, y)\) ដែលមានចម្ងាយពី \(F(2, 3)\) ស្មើនឹងចម្ងាយពីបន្ទាត់ \(\Delta: y = -1\) រួចបញ្ជាក់កំពូល និងប្រវែងអង្កត់ធ្នូកាត់កំណុំកែងអ័ក្សឆ្លុះ ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាងចំណុច \(M(x, y)\) តាមនិយមន័យ \(MF = d(M, \Delta)\) (1 ពិន្ទុ)
សរសេរ \(\sqrt{(x - 2)^2 + (y - 3)^2} = |y + 1|\) (1 ពិន្ទុ)
លើកជាការេទាំងសងខាង៖ \((x - 2)^2 + y^2 - 6y + 9 = y^2 + 2y + 1\) (1 ពិន្ទុ)
សម្រួលបានសមីការស្ដង់ដារ \((x - 2)^2 = 8(y - 1)\) (1 ពិន្ទុ)
កំពូលគឺ \(I(2, 1)\) និងប្រវែងអង្កត់ធ្នូកាត់កំណុំកែងអ័ក្សឆ្លុះស្មើ \(|4p| = 8\) ។ (1 ពិន្ទុ)', 'និយមន័យប៉ារ៉ាបូល', 'hard', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22545, 'រកសមីការបន្ទាត់ប៉ះប៉ារ៉ាបូល \(x^2 - 4x - 4y = 0\) ដែលស្របនឹងបន្ទាត់ \(2x - y + 7 = 0\) រួចរកកូអរដោនេចំណុចប៉ះ ។', NULL, '[]', 0, NULL, 5, 'writing', 'បន្ទាត់ស្របនឹង \(2x - y + 7 = 0\) មានសមីការ \(y = 2x + c\) (1 ពិន្ទុ)
ជំនួស \(y = 2x + c\) ចូលសមីការប៉ារ៉ាបូលបាន \(x^2 - 12x - 4c = 0\) (1 ពិន្ទុ)
លក្ខខណ្ឌប៉ះ \(\Delta'' = 36 + 4c = 0 \Rightarrow c = -9\) (1 ពិន្ទុ)
ដូច្នេះសមីការបន្ទាត់ប៉ះគឺ \(y = 2x - 9\) ឬ \(2x - y - 9 = 0\) (1 ពិន្ទុ)
អាប់ស៊ីសចំណុចប៉ះ \(x = 6\) និង \(y = 2(6) - 9 = 3\) បានចំណុចប៉ះ \((6, 3)\) ។ (1 ពិន្ទុ)', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'hard', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
