INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22546, 'ចង្ក្រានថាមពលព្រះអាទិត្យរាងប៉ារ៉ាបូលមួយមានមាត់អង្កត់ផ្ចិត \(2.4\text{ m}\) និងជម្រៅ \(0.45\text{ m}\) ។ ក. រកសមីការប៉ារ៉ាបូល និងកម្ពស់កំណុំ \(p\) ពីបាតចង្ក្រាន ។ ខ. រកទទឹងផ្ទៃកាត់នៅកម្ពស់ \(y = 0.20\text{ m}\) ពីបាតចង្ក្រាន ។', 'g12sc-a6782b8f4e.svg', '[]', 0, NULL, 5, 'writing', 'ដាក់កំពូលនៅ \(O(0, 0)\) សមីការមានរាង \(x^2 = 4py\) កាត់តាម \((1.2, 0.45)\) (1 ពិន្ទុ)
ជំនួស \(1.2^2 = 4p(0.45) \Rightarrow 1.44 = 1.8p \Rightarrow p = 0.8\text{ m}\) (1 ពិន្ទុ)
ដូច្នេះសមីការប៉ារ៉ាបូលគឺ \(x^2 = 3.2y\) និងកំណុំស្ថិតនៅ \(0.8\text{ m}\) ពីបាត (1 ពិន្ទុ)
ជំនួស \(y = 0.20\) បាន \(x^2 = 3.2(0.20) = 0.64 \Rightarrow x = \pm 0.8\text{ m}\) (1 ពិន្ទុ)
ទទឹងផ្ទៃកាត់នៅកម្ពស់ \(0.20\text{ m}\) គឺ \(2 \times 0.8 = 1.6\text{ m}\) ។ (1 ពិន្ទុ)', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'pisa', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-d708bafa35.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22547, 'ផ្លូវរូងក្រោមដីមួយមានផ្ទៃកាត់រាងប៉ារ៉ាបូល ទទឹងបាត \(12\text{ m}\) និងកម្ពស់នៅចំណុចកណ្ដាល \(9\text{ m}\) ។ ក. រកសមីការប៉ារ៉ាបូល ។ ខ. តើរថយន្តដឹកទំនិញទទឹង \(4\text{ m}\) និងកម្ពស់ \(7.5\text{ m}\) អាចបើកកាត់តាមកណ្ដាលផ្លូវរូងបានឬទេ?', 'g12sc-d708bafa35.svg', '[]', 0, NULL, 5, 'writing', 'តាងបាតផ្លូវជាអ័ក្ស \(Ox\) កំពូល \(I(0, 9)\) បានសមីការ \(x^2 = 4p(y - 9)\) (1 ពិន្ទុ)
កាត់តាមគែមបាត \((6, 0)\) បាន \(36 = 4p(-9) \Rightarrow 4p = -4\) (1 ពិន្ទុ)
សមីការប៉ារ៉ាបូលគឺ \(x^2 = -4(y - 9)\) ឬ \(y = 9 - \frac{x^2}{4}\) (1 ពិន្ទុ)
រថយន្តទទឹង \(4\text{ m}\) ត្រូវនឹង \(x = \pm 2\) បានកម្ពស់ផ្លូវរូង \(y = 9 - \frac{4}{4} = 8\text{ m}\) (1 ពិន្ទុ)
ដោយ \(8\text{ m} > 7.5\text{ m}\) (សល់ចន្លោះ \(0.5\text{ m}\)) ដូច្នេះរថយន្តអាចបើកកាត់បានដោយសុវត្ថិភាព ។ (1 ពិន្ទុ)', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'pisa', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Evaluate');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-fec293f67a.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22548, 'ខ្សែកាបរាងប៉ារ៉ាបូលនៃស្ពានយោលមួយមានចម្ងាយរវាងប៉មទាំងពីរ \(80\text{ m}\) ចំណុចទាបបំផុតនៅខ្ពស់ \(5\text{ m}\) ពីផ្លូវស្ពាន ហើយចុងខ្សែនៅលើប៉មខ្ពស់ \(25\text{ m}\) ។ ក. រកសមីការប៉ារ៉ាបូល ។ ខ. រកប្រវែងខ្សែទ្រឈរនៅចម្ងាយ \(10\text{ m}\) និង \(20\text{ m}\) ពីចំណុចកណ្ដាល ។', 'g12sc-fec293f67a.svg', '[]', 0, NULL, 5, 'writing', 'ដាក់កំពូលនៅ \(I(0, 5)\) សមីការមានរាង \(x^2 = 4p(y - 5)\) (1 ពិន្ទុ)
ជំនួសកំពូលប៉ម \((40, 25)\) បាន \(40^2 = 4p(25 - 5) \Rightarrow 1\,600 = 80p \Rightarrow 4p = 80\) (1 ពិន្ទុ)
សមីការប៉ារ៉ាបូលគឺ \(x^2 = 80(y - 5)\) ឬ \(y = 5 + \frac{x^2}{80}\) (1 ពិន្ទុ)
ត្រង់ \(x = 10\text{ m}\) បានប្រវែងខ្សែ \(y = 5 + \frac{100}{80} = 6.25\text{ m}\) (1 ពិន្ទុ)
ត្រង់ \(x = 20\text{ m}\) បានប្រវែងខ្សែ \(y = 5 + \frac{400}{80} = 10\text{ m}\) ។ (1 ពិន្ទុ)', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'pisa', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-00f015114c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22549, 'ធ្នូទឹកបាញ់រាងប៉ារ៉ាបូលមួយចេញពីចំណុច \(O(0, 0)\) ឡើងដល់ចំណុចកំពូល \(I(4, 3.2)\) (ឯកតាគិតជាម៉ែត្រ) ។ ក. រកសមីការគន្លងទឹក ។ ខ. រកចំណុចធ្លាក់ដល់ដីវិញ និងកម្ពស់ធ្នូទឹកត្រង់ \(x = 6\text{ m}\) ។', 'g12sc-00f015114c.svg', '[]', 0, NULL, 5, 'writing', 'សរសេរសមីការរាង \((x - 4)^2 = 4p(y - 3.2)\) (1 ពិន្ទុ)
ជំនួសគល់ \((0, 0)\) បាន \(16 = 4p(-3.2) \Rightarrow 4p = -5\) (1 ពិន្ទុ)
សមីការគន្លងទឹកគឺ \((x - 4)^2 = -5(y - 3.2)\) ឬ \(y = 3.2 - 0.2(x - 4)^2\) (1 ពិន្ទុ)
ទឹកធ្លាក់ដល់ដី \(y = 0 \Rightarrow (x - 4)^2 = 16 \Rightarrow x = 8\text{ m}\) ត្រង់ \((8, 0)\) (1 ពិន្ទុ)
ត្រង់ \(x = 6\text{ m}\) បានកម្ពស់ \(y = 3.2 - 0.2(6 - 4)^2 = 2.4\text{ m}\) ។ (1 ពិន្ទុ)', 'បន្ទាត់ប៉ះប៉ារ៉ាបូល និងអនុវត្តប៉ារ៉ាបូល', 'pisa', 0, '12SC', 'ប៉ារ៉ាបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
